from .money import MAX_AMOUNT, add_amounts, format_amount, parse_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    items = list(amounts)  # snapshot; never mutate the caller's list
    parsed = [parse_amount(item) for item in items]
    total = add_amounts(parsed)
    if total > MAX_AMOUNT:
        raise ValueError("total exceeds maximum")
    return {"total": format_amount(total), "count": len(parsed)}

