import re
from decimal import (
    Context,
    Decimal,
    Inexact,
    InvalidOperation,
    MAX_EMAX,
    MIN_EMIN,
)

_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")

# Private, high-precision context used for all arithmetic so results never
# depend on (or modify) the caller's thread-local decimal context.  Inexact
# results are trapped, so operations are either exact or raise (dropping
# trailing zeros is not inexact and is allowed).
_EXACT = Context(
    prec=100,
    Emax=MAX_EMAX,
    Emin=MIN_EMIN,
    traps=[InvalidOperation, Inexact],
)


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)  # exact, context-independent
    if isinstance(value, str):
        if _AMOUNT_RE.fullmatch(value) is None:
            raise ValueError("invalid amount string: %r" % (value,))
        return Decimal(value)  # exact, context-independent
    raise ValueError("unsupported amount type: %s" % type(value).__name__)


def _check_cents(dec):
    """Validate a finite, positive, in-range Decimal and return it with exponent -2."""
    if not dec.is_finite():
        raise ValueError("amount must be finite")
    # Comparisons between finite Decimals are exact and context-independent.
    if dec <= 0:
        raise ValueError("amount must be positive")
    if dec > MAX_AMOUNT:
        raise ValueError("amount exceeds maximum")
    try:
        return dec.quantize(_CENT, context=_EXACT)
    except (Inexact, InvalidOperation):
        raise ValueError("amount is not exactly representable in cents") from None


def parse_amount(value):
    return _check_cents(_to_decimal(value))


def add_amounts(amounts):
    """Exactly sum already-parsed amounts; returns a Decimal with exponent -2."""
    total = Decimal("0.00")
    for amount in amounts:
        total = _EXACT.add(total, amount)
    return total


def format_amount(value):
    return format(value, ".2f")
